const b = $input.first().json;
const att = (b.attachments || [])[0] || null;

let msgType = 'text';
let attUrl = null, attMime = 'text/plain';
if (att) {
  const ft = (att.file_type || '').toLowerCase();
  attUrl = att.file_url || att.data_url || null;
  if (ft === 'audio' || ft === 'voice') { msgType = 'audio'; attMime = 'audio/ogg'; }
  else if (ft === 'image') { msgType = 'image'; attMime = 'image/jpeg'; }
  else if (ft === 'document' || ft === 'file' || ft === 'sticker') {
    msgType = 'document'; attMime = 'application/pdf';
  }
}

return [{ json: {
  inbox_id: String(b.inbox?.id || b.conversation?.inbox_id || ''),
  chatwoot_conversation_id: b.conversation?.id,
  message_id: b.id,
  content: b.content || '',
  sender_name: b.sender?.name || b.contact?.name || 'Cliente',
  sender_phone: b.sender?.phone_number || b.contact?.phone_number || '',
  contact_id: b.sender?.id || b.contact?.id || null,
  msg_type: msgType,
  att_url: attUrl,
  att_mime: attMime,
}}];

const ctx = $('🗂️ Montar Contexto').first().json;
const binData = $input.first().binary?.data?.data || '';
const base64 = Buffer.from(binData, 'base64').toString('base64');
const apiKey = ctx.gemini_key || $env.GEMINI_API_KEY;

const res = await $http.request({
  method: 'POST',
  url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`,
  headers: {'Content-Type': 'application/json'},
  body: JSON.stringify({
    contents: [{parts: [
      {inline_data: {mime_type: ctx.att_mime || 'audio/ogg', data: base64}},
      {text: 'Transcreva exatamente o que foi dito neste áudio em português brasileiro. Retorne apenas a transcrição, sem comentários.'}
    ]}],
    generationConfig: {temperature: 0.1, maxOutputTokens: 512}
  })
});
const transcribed = res?.candidates?.[0]?.content?.parts?.[0]?.text || '[áudio não transcrito]';
return [{ json: { ...ctx, content: transcribed, transcribed: true, media_base64: null }}];

const ctx = $('🗂️ Montar Contexto').first().json;
const binData = $input.first().binary?.data?.data || '';
const base64 = Buffer.from(binData, 'base64').toString('base64');
return [{ json: { ...ctx, media_base64: base64, media_type: 'image' }}];

const ctx = $('🗂️ Montar Contexto').first().json;
const binData = $input.first().binary?.data?.data || '';
const base64 = Buffer.from(binData, 'base64').toString('base64');
return [{ json: { ...ctx, media_base64: base64, media_type: 'document' }}];

const ctx = $('🔗 Unificar Branches').first().json;
const histRaw = $('📜 Buscar Histórico').first().json;
const history = Array.isArray(histRaw) ? histRaw.reverse() : [];
const feat = ctx.agent_features || {};

// Histórico formatado
const histText = history.map(m => {
  const role = m.role === 'assistant' ? `${ctx.agent_name}` : ctx.sender_name;
  return `${role}: ${m.content}`;
}).join('\n') || '(início da conversa)';

// System prompt
const systemPrompt = `Você é ${ctx.agent_name}, agente de atendimento via ${ctx.agent_channel}.

PERSONALIDADE: ${ctx.agent_personality}

INSTRUÇÕES:
${ctx.agent_instructions}

EMPRESA: ${ctx.client_name}

REGRAS:
- Responda SEMPRE em português brasileiro
- Seja natural, como numa conversa real de WhatsApp
- Mensagens curtas e diretas
- Não mencione que é IA a menos que perguntado diretamente
- Nunca quebre o personagem

HISTÓRICO:
${histText}`;

// Partes do conteúdo para Gemini
let parts = [];

if (ctx.media_base64 && ctx.media_type === 'image') {
  parts.push({inline_data: {mime_type: ctx.att_mime || 'image/jpeg', data: ctx.media_base64}});
  parts.push({text: ctx.content
    ? `O cliente enviou esta imagem com a mensagem: "${ctx.content}". Analise a imagem e responda.`
    : 'O cliente enviou esta imagem. Analise e responda adequadamente.'});
} else if (ctx.media_base64 && ctx.media_type === 'document') {
  parts.push({inline_data: {mime_type: ctx.att_mime || 'application/pdf', data: ctx.media_base64}});
  parts.push({text: ctx.content
    ? `O cliente enviou este documento com a mensagem: "${ctx.content}". Leia o documento e responda.`
    : 'O cliente enviou este documento. Leia e responda.'});
} else {
  parts.push({text: `${ctx.sender_name}: ${ctx.content}`});
}

// Instruções internas de features
let internalNotes = '';
if (feat.feat_qualify_lead) {
  internalNotes += '\n\n[SISTEMA] Ao responder, avalie internamente o score deste lead de 0 a 10. No FINAL da sua resposta adicione exatamente: |||SCORE:N||| onde N é o número.';
}
if (feat.feat_urgency_detection) {
  const urgWords = ['urgente','emergência','urgência','socorro','dor forte','sangue','acidente','agora mesmo'];
  const isUrgent = urgWords.some(w => (ctx.content||'').toLowerCase().includes(w));
  if (isUrgent) internalNotes += '\n\n[SISTEMA] URGÊNCIA DETECTADA — priorize e acolha o cliente imediatamente.';
}
if (feat.feat_send_cta) {
  const ctaWords = ['preço','valor','quanto','comprar','contratar','plano','assinar'];
  const wantsCTA = ctaWords.some(w => (ctx.content||'').toLowerCase().includes(w));
  if (wantsCTA) internalNotes += '\n\n[SISTEMA] Cliente demonstrou interesse comercial. Inclua uma chamada para ação clara na resposta.';
}

const finalSystem = systemPrompt + internalNotes;

// Detecções de features
const schedWords = ['agendar','marcar','horário','consulta','reunião','quando','disponível','data','agenda'];
const humanWords = ['falar com pessoa','atendente humano','gerente','reclamação','falar com alguém'];
const urgWords2 = ['urgente','emergência','socorro','agora mesmo','dor forte'];

const syncResp = $('🔄 Sincronizar Conversa').first().json;
return [{ json: {
  ...ctx,
  conversation_id: syncResp.conversation_id || null,
  lead_id: syncResp.lead_id || null,
  system_prompt: finalSystem,
  gemini_parts: parts,
  apiKey: ctx.groq_api_key || ctx.gemini_key || '',
  wants_scheduling: feat.feat_scheduling && schedWords.some(w => (ctx.content||'').toLowerCase().includes(w)),
  wants_human: feat.feat_escalate_human && humanWords.some(w => (ctx.content||'').toLowerCase().includes(w)),
  is_urgent: feat.feat_urgency_detection && urgWords2.some(w => (ctx.content||'').toLowerCase().includes(w)),
}}];

const ctx = $input.first().json;
const apiKey = ctx.apiKey;
if (!apiKey) {
  console.log("Sem chave Groq para este agente. Ignorando.");
  return [];
}

// Montar messages no formato OpenAI (compatível com Groq)
const messages = [
  { role: "system", content: ctx.system_prompt }
];

// Adicionar conteúdo da mensagem atual
if (ctx.media_base64 && ctx.media_type === "image") {
  messages.push({
    role: "user",
    content: [
      { type: "image_url", image_url: { url: `data:${ctx.att_mime || "image/jpeg"};base64,${ctx.media_base64}` }},
      { type: "text", text: ctx.content ? `${ctx.sender_name}: ${ctx.content}` : `${ctx.sender_name} enviou uma imagem.` }
    ]
  });
} else {
  messages.push({ role: "user", content: `${ctx.sender_name}: ${ctx.content}` });
}

const payload = {
  model: "llama-3.3-70b-versatile",
  messages: messages,
  temperature: 0.75,
  max_tokens: 1024,
};

const res = await $http.request({
  method: "POST",
  url: "https://api.groq.com/openai/v1/chat/completions",
  headers: {
    "Content-Type": "application/json",
    "Authorization": `Bearer ${apiKey}`
  },
  body: JSON.stringify(payload)
});

let rawText = res?.choices?.[0]?.message?.content || "Desculpe, não consegui processar. Pode repetir?";

// Extrair score se presente
let leadScore = null;
const scoreMatch = rawText.match(/\|\|\|SCORE:(\d+)\|\|\|/);
if (scoreMatch) {
  leadScore = parseInt(scoreMatch[1]);
  rawText = rawText.replace(/\|\|\|SCORE:\d+\|\|\|/, "").trim();
}

// Extrair tag de agendamento |||AGENDAR:email|||
let scheduleEmail = null;
let wantsSchedulingFromTag = false;
const agendarMatch = rawText.match(/\|\|\|AGENDAR:([^|]+)\|\|\|/);
if (agendarMatch) {
  scheduleEmail = agendarMatch[1].trim();
  wantsSchedulingFromTag = true;
  rawText = rawText.replace(/\|\|\|AGENDAR:[^|]+\|\|\|/, "").trim();
}

return [{ json: {
  ...ctx,
  response_text: rawText,
  lead_score: leadScore,
  wants_scheduling: wantsSchedulingFromTag || ctx.wants_scheduling || false,
  schedule_email: scheduleEmail || ctx.lead_email || null,
}}];

// Busca dados das etapas anteriores do workflow
const syncData = $('🔄 Sincronizar Conversa').first().json;
const ctxData = $('🗂️ Montar Contexto').first().json;
const groqData = $('🧠 Chamar Groq').first().json;

const agentId = ctxData.agent_id;
const leadId = syncData.lead_id || groqData.lead_id || null;
const leadName = ctxData.sender_name || 'Lead';
const leadPhone = ctxData.sender_phone || null;
const leadEmail = groqData.schedule_email || null;

// Data padrão: amanhã às 10h (BRT)
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
tomorrow.setHours(13, 0, 0, 0); // 10h BRT = 13h UTC
const end = new Date(tomorrow.getTime() + 60 * 60 * 1000);

const startDt = tomorrow.toISOString();
const endDt = end.toISOString();

// Chama a API interna — cria evento no Google Calendar + Google Meet + salva no banco
const res = await $http.request({
  method: 'POST',
  url: 'https://app.atendimentoia.cloud/api/internal/calendar/create-event',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    agent_id: agentId,
    lead_id: leadId,
    lead_name: leadName,
    lead_phone: leadPhone,
    lead_email: leadEmail,
    attendee_emails: leadEmail ? [leadEmail] : [],
    summary: `Atendimento: ${leadName}`,
    description: `Lead: ${leadName}\nTelefone: ${leadPhone}\nEmail: ${leadEmail || 'não informado'}\nAgente IA: ${ctxData.agent_name || ''}\nEmpresa: ${ctxData.client_name || ''}`,
    start_datetime: startDt,
    end_datetime: endDt,
    timezone: 'America/Sao_Paulo',
  })
});

return [{ json: {
  ...ctxData,
  calendar_event_id: res.event_id || null,
  appointment_id: res.appointment_id || null,
  event_link: res.event_link || null,
  meet_link: res.meet_link || null,
  schedule_email: leadEmail,
}}];
